display.text:
use std::sync::Arc;

use axum::http::{StatusCode, header};
use sqlx::SqlitePool;

use crate::audit::{self, AuditRecord};
use crate::config::Config;
use crate::error::ToolError;
use crate::internal_client::InternalClient;
use crate::mcp_grant::McpGrant;
use crate::oauth::{self, TokenValidationResult};
use crate::rate_limiter::RateLimiter;
use crate::tools::{self, AuthorizedToolContext};

#[derive(Clone)]
pub struct Gateway {
    pub config: Config,
    pub db_pool: SqlitePool,
    pub internal_client: InternalClient,
    pub rate_limiter: Arc<RateLimiter>,
}

impl Gateway {
    pub fn new(
        config: Config,
        db_pool: SqlitePool,
    ) -> Result<Self, Vec<crate::config::ConfigError>> {
        let internal_client = InternalClient::new(
            config.internal_api_base.clone(),
            config.internal_api_key.clone(),
        )
        .map_err(|e| vec![e])?;

        let rate_limiter = if config.rate_limit_enabled {
            Arc::new(RateLimiter::new())
        } else {
            Arc::new(RateLimiter::disabled())
        };

        Ok(Self {
            config,
            db_pool,
            internal_client,
            rate_limiter,
        })
    }

    /// Extract the OAuth bearer token from the request Authorization header.
    fn extract_bearer_token(
        headers: &axum::http::HeaderMap,
    ) -> Result<String, axum::http::Response<axum::body::Body>> {
        let auth_header = headers
            .get(axum::http::header::AUTHORIZATION)
            .ok_or_else(|| unauthorized_response(None, "missing authorization header"))?;

        let auth_str = auth_header
            .to_str()
            .map_err(|_| unauthorized_response(None, "invalid authorization header encoding"))?;

        if !auth_str.starts_with("Bearer ") {
            return Err(unauthorized_response(
                None,
                "authorization must use Bearer scheme",
            ));
        }

        let token = &auth_str[7..];
        if token.is_empty() {
            return Err(unauthorized_response(None, "empty bearer token"));
        }

        Ok(token.to_string())
    }

    /// Validate the OAuth token and return the TokenValidationResult.
    async fn validate_token(
        &self,
        token: &str,
    ) -> Result<TokenValidationResult, axum::http::Response<axum::body::Body>> {
        let resource = &self.config.public_resource_url;
        let result = oauth::validate_access_token(token, &self.config.oauth_issuer, resource)
            .await
            .map_err(|e| {
                tracing::warn!(error = %e, "token validation failed");
                unauthorized_response_from_token_error(&e)
            })?;

        tracing::info!(
            user_id = result.user_id,
            client_id = result.oauth_client_id,
            "token validated"
        );

        Ok(result)
    }

    /// Check Origin header against allowed origins.
    fn check_origin(&self, _request: &axum::http::Request<axum::body::Body>) -> bool {
        // No origin configuration — allow all (loopback/dev mode)
        true
    }

    /// Handle an incoming MCP request.
    ///
    /// This is the entry point for all MCP protocol communication.
    /// It validates the OAuth token, dispatches to the appropriate tool,
    /// records the invocation in the local audit log, and returns a
    /// structured MCP response.
    pub async fn handle_mcp_request(
        &self,
        request_id: String,
        request: axum::http::Request<axum::body::Body>,
    ) -> axum::http::Response<axum::body::Body> {
        // Check Origin/CORS
        if !self.check_origin(&request) {
            return axum::http::Response::builder()
                .status(StatusCode::FORBIDDEN)
                .body(axum::body::Body::from(
                    serde_json::to_string(&serde_json::json!({
                        "error": {
                            "code": -2001,
                            "message": "origin not allowed",
                        },
                    }))
                    .unwrap(),
                ))
                .unwrap();
        }

        let (request_parts, request_body) = request.into_parts();

        // Parse the MCP protocol message from the request body.
        // Limit body size to 1MB to prevent memory exhaustion DoS.
        let body_bytes = match axum::body::to_bytes(request_body, 1024 * 1024).await {
            Ok(b) => b,
            Err(e) => {
                tracing::error!(error = %e, "failed to read request body");
                return axum::http::Response::builder()
                    .status(axum::http::StatusCode::BAD_REQUEST)
                    .body(axum::body::Body::from(r#"{"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":"parse error"}}"#).into())
                    .unwrap();
            }
        };

        let message: serde_json::Value = match serde_json::from_slice(&body_bytes) {
            Ok(v) => v,
            Err(e) => {
                tracing::error!(error = %e, "failed to parse MCP message");
                return axum::http::Response::builder()
                    .status(axum::http::StatusCode::BAD_REQUEST)
                    .body(axum::body::Body::from(r#"{"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":"parse error"}}"#).into())
                    .unwrap();
            }
        };

        let method = message.get("method").and_then(|v| v.as_str()).unwrap_or("");

        match method {
            "tools/list" => self.handle_tools_list(&message).await,
            "tools/call" => {
                self.handle_tools_call(&request_id, &request_parts.headers, &message)
                    .await
            }
            _ => {
                tracing::warn!(method = %method, "unknown MCP method");
                axum::http::Response::builder()
                    .status(axum::http::StatusCode::BAD_REQUEST)
                    .body(
                        axum::body::Body::from(
                            serde_json::to_string(&serde_json::json!({
                                "jsonrpc": "2.0",
                                "id": message.get("id"),
                                "error": {
                                    "code": -32601,
                                    "message": format!("Method not found: {}", method),
                                },
                            }))
                            .unwrap(),
                        )
                        .into(),
                    )
                    .unwrap()
            }
        }
    }

    /// Handle tools/list — return the full tool catalog with all nine tools.
    async fn handle_tools_list(
        &self,
        message: &serde_json::Value,
    ) -> axum::http::Response<axum::body::Body> {
        let tools = tools::list_tools();
        let tools_array: Vec<serde_json::Value> = tools
            .iter()
            .map(|name| serde_json::json!({ "name": name }))
            .collect();

        let response = serde_json::json!({
            "jsonrpc": "2.0",
            "result": {
                "tools": tools_array
            }
        });

        axum::http::Response::builder()
            .status(axum::http::StatusCode::OK)
            .header("content-type", "application/json")
            .body(axum::body::Body::from(
                serde_json::to_string_pretty(&response).unwrap(),
            ))
            .unwrap()
    }

    /// Handle tools/call — validate token, then run the authorized call path.
    async fn handle_tools_call(
        &self,
        request_id: &str,
        headers: &axum::http::HeaderMap,
        message: &serde_json::Value,
    ) -> axum::http::Response<axum::body::Body> {
        // Rate limiting check
        if !self.rate_limiter.check("mcp_tool", 100, 60) {
            return axum::http::Response::builder()
                .status(StatusCode::TOO_MANY_REQUESTS)
                .header("content-type", "application/json")
                .body(axum::body::Body::from(
                    serde_json::to_string(&serde_json::json!({
                        "jsonrpc": "2.0",
                        "id": message.get("id"),
                        "error": {
                            "code": -2004,
                            "message": "rate limit exceeded",
                        },
                    }))
                    .unwrap(),
                ))
                .unwrap();
        }

        // Extract and validate bearer token
        let token = match Self::extract_bearer_token(headers) {
            Ok(t) => t,
            Err(resp) => return resp,
        };

        // Validate token
        let token_result = match self.validate_token(&token).await {
            Ok(r) => r,
            Err(resp) => return resp,
        };

        self.handle_authorized_tool_call(request_id, &token_result, message)
            .await
    }

    /// Run an already-authenticated tools/call: resolve the authoritative
    /// grant, dispatch to the tool, and record the invocation in the local
    /// audit log.
    ///
    /// Audit recording is best-effort: a failed audit insert is logged as an
    /// operational error and never replaces an already-completed tool response.
    /// Returning failure would encourage a client to repeat a mutation that
    /// already succeeded.
    pub async fn handle_authorized_tool_call(
        &self,
        request_id: &str,
        token_result: &TokenValidationResult,
        message: &serde_json::Value,
    ) -> axum::http::Response<axum::body::Body> {
        // Extract tool name and params
        let tool_name = message
            .get("params")
            .and_then(|p| p.get("name"))
            .and_then(|n| n.as_str())
            .unwrap_or("");

        let params = message
            .get("params")
            .and_then(|p| p.get("arguments"))
            .cloned()
            .unwrap_or(serde_json::json!({}));

        let auth_strength = token_result.auth_strength.to_string();

        // Resolve the authoritative grant from CommonCal core (source of truth).
        let grant = match self
            .internal_client
            .get_mcp_grant(token_result.user_id, &token_result.oauth_client_id)
            .await
        {
            Ok(Some(resp)) => McpGrant::from(resp),
            Ok(None) => {
                self.record_audit(
                    &AuditRecord {
                        request_id,
                        user_id: token_result.user_id,
                        client_id: &token_result.oauth_client_id,
                        grant_id: None,
                        tool: tool_name,
                        resource_ids: None,
                        auth_result: "denied",
                        scope: None,
                        auth_strength: &auth_strength,
                        latency_ms: 0,
                        result_type: "denied",
                        operation_id: None,
                    },
                )
                .await;
                return axum::http::Response::builder()
                    .status(StatusCode::FORBIDDEN)
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(
                        serde_json::to_string(&serde_json::json!({
                            "jsonrpc": "2.0",
                            "id": message.get("id"),
                            "error": {
                                "code": -2003,
                                "message": "no MCP grant found",
                            },
                        }))
                        .unwrap(),
                    ))
                    .unwrap();
            }
            Err(e) => {
                self.record_audit(
                    &AuditRecord {
                        request_id,
                        user_id: token_result.user_id,
                        client_id: &token_result.oauth_client_id,
                        grant_id: None,
                        tool: tool_name,
                        resource_ids: None,
                        auth_result: "denied",
                        scope: None,
                        auth_strength: &auth_strength,
                        latency_ms: 0,
                        result_type: "error",
                        operation_id: None,
                    },
                )
                .await;
                return axum::http::Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(
                        serde_json::to_string(&serde_json::json!({
                            "jsonrpc": "2.0",
                            "id": message.get("id"),
                            "error": {
                                "code": -2005,
                                "message": format!("grant resolution failed: {}", e),
                            },
                        }))
                        .unwrap(),
                    ))
                    .unwrap();
            }
        };

        // Build the authorized context and dispatch to the tool.
        let context = AuthorizedToolContext {
            token: token_result,
            grant: &grant,
            internal_client: &self.internal_client,
        };

        let started = std::time::Instant::now();
        match tools::dispatch(&context, tool_name, params).await {
            Ok(response) => {
                self.record_audit(
                    &AuditRecord {
                        request_id,
                        user_id: token_result.user_id,
                        client_id: &token_result.oauth_client_id,
                        grant_id: Some(&grant.grant_id),
                        tool: tool_name,
                        resource_ids: None,
                        auth_result: "allowed",
                        scope: None,
                        auth_strength: &auth_strength,
                        latency_ms: started.elapsed().as_millis() as i64,
                        result_type: "success",
                        operation_id: None,
                    },
                )
                .await;
                response
            }
            Err(e) => {
                let (auth_result, result_type) = match e {
                    ToolError::Unauthorized(_) | ToolError::Forbidden(_) => {
                        ("denied", "denied")
                    }
                    _ => ("allowed", "error"),
                };
                self.record_audit(
                    &AuditRecord {
                        request_id,
                        user_id: token_result.user_id,
                        client_id: &token_result.oauth_client_id,
                        grant_id: Some(&grant.grant_id),
                        tool: tool_name,
                        resource_ids: None,
                        auth_result,
                        scope: None,
                        auth_strength: &auth_strength,
                        latency_ms: started.elapsed().as_millis() as i64,
                        result_type,
                        operation_id: None,
                    },
                )
                .await;
                let mcp_error = e.to_mcp_error(message.get("id"));
                axum::http::Response::builder()
                    .status(StatusCode::OK)
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(
                        serde_json::to_string(&serde_json::json!({
                            "jsonrpc": "2.0",
                            "id": message.get("id"),
                            "error": {
                            "code": mcp_error["error"]["code"],
                            "message": mcp_error["error"]["message"],
                            },
                        }))
                        .unwrap(),
                    ))
                    .unwrap()
            }
        }
    }

    /// Best-effort audit insert. Failures are logged, never propagated.
    async fn record_audit(&self, record: &AuditRecord<'_>) {
        if let Err(e) = audit::log_invocation(&self.db_pool, record).await {
            tracing::error!(
                error = %e,
                tool = record.tool,
                request_id = record.request_id,
                "failed to record MCP audit"
            );
        }
    }

    async fn handle_calendar_list(
        &self,
        message: &serde_json::Value,
    ) -> axum::http::Response<axum::body::Body> {
        // Delegated to tools/call handler
        self.handle_tools_list(message).await
    }
}

/// Build a 401 Unauthorized MCP error response with WWW-Authenticate header.
fn unauthorized_response(
    reason: Option<String>,
    msg: &str,
) -> axum::http::Response<axum::body::Body> {
    let mut challenge = format!(
        "Bearer realm=\"mcp\", resource_metadata=\"{}/.well-known/oauth-protected-resource\"",
        "http://127.0.0.1:3001"
    );
    if let Some(ref r) = reason {
        let sanitized = sanitize_error(r);
        challenge.push_str(&format!(", error=\"{}\"", sanitized));
    }
    axum::http::Response::builder()
        .status(StatusCode::UNAUTHORIZED)
        .header(header::WWW_AUTHENTICATE, challenge)
        .header("content-type", "application/json")
        .body(axum::body::Body::from(
            serde_json::to_string(&serde_json::json!({
                "error": {
                    "code": -2000,
                    "message": msg,
                },
            }))
            .unwrap(),
        ))
        .unwrap()
}

/// Build a 401 response from a token validation error with appropriate WWW-Authenticate.
fn unauthorized_response_from_token_error(
    error: &crate::error::TokenError,
) -> axum::http::Response<axum::body::Body> {
    let (http_code, error_param, msg) = match error {
        crate::error::TokenError::Expired => (
            StatusCode::UNAUTHORIZED,
            "token_expired",
            "access token has expired",
        ),
        crate::error::TokenError::InvalidAudience => (
            StatusCode::UNAUTHORIZED,
            "invalid_resource",
            "token audience does not match this resource",
        ),
        crate::error::TokenError::InvalidIssuer => (
            StatusCode::UNAUTHORIZED,
            "invalid_issuer",
            "token issuer is not trusted",
        ),
        crate::error::TokenError::Revoked => (
            StatusCode::UNAUTHORIZED,
            "invalid_token",
            "token has been revoked",
        ),
        crate::error::TokenError::MissingToken => (
            StatusCode::UNAUTHORIZED,
            "missing_token",
            "authorization token is required",
        ),
        _ => (
            StatusCode::UNAUTHORIZED,
            "invalid_token",
            "invalid authorization token",
        ),
    };

    let mut challenge = format!(
        "Bearer realm=\"mcp\", resource_metadata=\"{}/.well-known/oauth-protected-resource\"",
        "http://127.0.0.1:3001"
    );
    challenge.push_str(&format!(", error=\"{}\"", error_param));

    axum::http::Response::builder()
        .status(http_code)
        .header(header::WWW_AUTHENTICATE, challenge)
        .header("content-type", "application/json")
        .body(axum::body::Body::from(
            serde_json::to_string(&serde_json::json!({
                "error": {
                    "code": -2000,
                    "message": msg,
                },
            }))
            .unwrap(),
        ))
        .unwrap()
}

/// Sanitize a string for use in WWW-Authenticate header value.
/// Escapes quotes and removes control characters.
fn sanitize_error(s: &str) -> String {
    s.chars()
        .filter(|c| !(*c as u32) < 0x20)
        .map(|c| if c == '"' { '\\' } else { c })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::Gateway;
    use axum::http::{HeaderMap, HeaderValue, StatusCode, header::AUTHORIZATION};

    #[test]
    fn extracts_bearer_token_from_original_request_headers() {
        let mut headers = HeaderMap::new();
        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_static("Bearer access-token"),
        );

        assert_eq!(
            Gateway::extract_bearer_token(&headers).expect("Bearer token should be accepted"),
            "access-token"
        );
    }

    #[test]
    fn rejects_missing_bearer_token() {
        let response = Gateway::extract_bearer_token(&HeaderMap::new())
            .expect_err("missing Authorization header should be rejected");

        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    }
}

